'use strict';
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6ZM2 14l10 6 10-6M2 18l10 6 10-6"/>',search:'<circle cx="10.8" cy="10.8" r="7.3"/><path d="m16 16 5 5"/>',building:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="M9 7h1m4 0h1M9 11h1m4 0h1m-6 4h1m4 0h1m-5 7v-3h4v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M7 3v4m10-4v4M7 14h3m4 0h3m-10 3h3"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3ZM20 2v4m-2-2h4"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v3l3 1 1 4h5l1-4 3-1 3-4-2-2V7l-3-1-2-3H9Z"/><circle cx="12" cy="12" r="3"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14l-1 7ZM12 21h9"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',laptop:'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="m4 16-2 4h20l-2-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',save:'<path d="M4 3h13l4 4v14H3V3ZM7 3v6h9V3M7 21v-8h10v8"/>',trash:'<path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 10-8 10S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c5 4 13 4 18 0M10 13h4"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 3 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`;}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);});}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='nexo.workspace.v1';
const defaultState=()=>({version:1,profile:{name:'Welington',title:'',city:'Brasília / DF',description:'',specialties:[],restrictions:'',portfolio:''},services:[],drafts:[]});
function validState(s){return s&&s.version===1&&s.profile&&['name','title','city','description','restrictions','portfolio'].every(k=>typeof s.profile[k]==='string'&&s.profile[k].length<=10000)&&Array.isArray(s.profile.specialties)&&s.profile.specialties.length<=50&&s.profile.specialties.every(x=>typeof x==='string'&&x.length<=100)&&Array.isArray(s.services)&&s.services.length<=500&&s.services.every(x=>x&&['id','name','specialty','deliverables','deadline','price','exclusions','proof'].every(k=>typeof x[k]==='string'&&x[k].length<=10000)&&typeof x.active==='boolean')&&new Set(s.services.map(x=>x.id)).size===s.services.length&&Array.isArray(s.drafts)&&s.drafts.length<=500&&s.drafts.every(d=>d&&['id','niche','state','city','neighborhood','createdAt'].every(k=>typeof d[k]==='string'&&d[k].length<=500)&&[5,10].includes(d.quantity));}
let state=defaultState(),storageProblem=false;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(!validState(parsed))throw Error('Formato de dados inválido');state=parsed;}}catch{storageProblem=true;}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;updateChrome();return true;}catch{toast('Não foi possível salvar. Verifique o espaço e as permissões do navegador.');return false;}}
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
const $=s=>document.querySelector(s);
const main=$('#main');
const names={inicio:'Visão geral',perfil:'Meu perfil profissional',servicos:'Meus serviços',pesquisa:'Encontrar empresas',empresas:'Minhas empresas',retornos:'Acompanhamento',configuracoes:'Configurações'};
let route='',serviceFilter='all',serviceSearch='',profileSelection=[];
const specialties=['Gestão de tráfego','Web design','Social media','Soluções com IA','Copywriting','Design gráfico'];
const serviceTemplates=[{name:'Gestão de campanhas Meta Ads',specialty:'Gestão de tráfego',deliverables:'Planejamento de campanhas, configuração e acompanhamento de anúncios na Meta.',exclusions:'Verba de mídia e produção audiovisual não incluídas.'},{name:'Criação de site institucional',specialty:'Web design',deliverables:'Site responsivo para apresentar o negócio, seus serviços e canais de contato.',exclusions:'Domínio e serviços de terceiros devem ser definidos na proposta.'},{name:'Gestão de redes sociais',specialty:'Social media',deliverables:'Planejamento editorial e conteúdo para as redes sociais acordadas na proposta.',exclusions:'Definir quantidade de peças, canais e produção presencial antes de oferecer.'},{name:'Automação de atendimento',specialty:'Soluções com IA',deliverables:'Mapeamento do atendimento e configuração de automações conforme os canais disponíveis.',exclusions:'Custos de APIs e plataformas devem ser definidos na proposta.'},{name:'Redação de páginas de venda',specialty:'Copywriting',deliverables:'Diagnóstico da oferta e redação de página de venda com benefícios e chamadas para ação.',exclusions:'Resultados comerciais não garantidos.'},{name:'Criação de peças digitais',specialty:'Design gráfico',deliverables:'Peças digitais adaptadas à identidade visual e aos formatos acordados.',exclusions:'Definir quantidade, formatos e rodadas de revisão na proposta.'}];
function completion(){return [Boolean(state.profile.description.trim()&&state.profile.specialties.length),state.services.some(s=>s.active),state.drafts.length>0].filter(Boolean).length;}
function updateChrome(){const first=state.profile.name.trim().split(/\s+/)[0]||'Meu perfil';$('#sideName').innerHTML=`${esc(first)}<small>Meu perfil profissional</small>`;document.querySelectorAll('.avatar').forEach(e=>e.textContent=(first[0]||'N').toUpperCase());$('#navCount').textContent=state.services.filter(s=>s.active).length;}
function heading(title,subtitle,actions=''){return `<div class="page-head"><div><span class="eyebrow">SEU ESPAÇO DE CONEXÕES</span><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function home(){const n=completion(),ready=n>=2;return heading(`Seu próximo cliente começa aqui.`,`Olá, ${esc(state.profile.name.split(' ')[0]||'Welington')}. Vamos conectar seu trabalho às oportunidades certas.`)+`
<section class="welcome"><div><span class="eyebrow">MENOS IMPROVISO. MAIS DIREÇÃO.</span><h2>O que você faz.<br>Quem precisa de você.</h2><p>Organize seus serviços, encontre oportunidades e prepare uma abordagem que faz sentido.</p><a class="btn" href="#${ready?'pesquisa':'perfil'}">${icon(ready?'search':'user')}${ready?'Preparar minha pesquisa':'Configurar meu perfil'}</a></div><div class="orbital" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orbit three"></div><div class="nexo-symbol">n</div><div class="sat a">${icon('user')}</div><div class="sat b">${icon('target')}</div><div class="sat c">${icon('briefcase')}</div></div></section>
<div class="stats"><a class="stat" href="#servicos"><div class="stat-icon">${icon('layers')}</div><div><div class="number">${String(state.services.filter(s=>s.active).length).padStart(2,'0')}</div><p>Serviços disponíveis</p></div></a><a class="stat" href="#empresas"><div class="stat-icon">${icon('building')}</div><div><div class="number">00</div><p>Empresas na sua lista</p></div></a><a class="stat" href="#pesquisa"><div class="stat-icon">${icon('search')}</div><div><div class="number">${String(state.drafts.length).padStart(2,'0')}</div><p>Pesquisas preparadas</p></div></a></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Prepare seu ponto de partida</h2><p>Seu NEXO, do seu jeito.</p></div><span class="status-pill">${n}/3 etapas</span></div><div class="panel-body"><div class="progress-caption"><span>Configuração inicial</span><span>${Math.round(n/3*100)}%</span></div><div class="progress-track"><span style="width:${n/3*100}%"></span></div><div class="setup-list">${[
['perfil','user','Conte o que você faz','Especialidades, entregas e seus diferenciais.',Boolean(state.profile.description.trim()&&state.profile.specialties.length),'Configurar'],
['servicos','layers','Monte seu catálogo','Confirme os serviços que quer oferecer.',state.services.some(s=>s.active),'Adicionar'],
['pesquisa','search','Defina sua primeira pesquisa','Escolha um nicho e uma localização.',state.drafts.length>0,'Preparar']].map(([r,ic,title,desc,done,action])=>`<div class="setup-item"><span class="step-marker ${done?'done':''}">${icon(done?'check':ic)}</span><div><h3>${title}</h3><p>${desc}</p></div><a href="#${r}">${done?'Revisar':action}</a></div>`).join('')}</div></div></section><aside class="dashboard-aside"><div class="tip-card"><div class="stat-icon">${icon('spark')}</div><p class="tip-label">A CONEXÃO CERTA</p><h3>Uma boa abordagem<br>começa por entender.</h3><p>Quanto mais claro for o seu serviço, mais relevante será a oferta para cada empresa.</p><a class="text-link" href="#servicos">Organizar meus serviços</a></div><div class="next-card"><h3>${icon('info')}Em construção, com você</h3><p>Perfil e serviços já funcionam. Busca com IA e diagnóstico entram na próxima etapa.</p></div></aside></div>`;}
function specialtyChips(){const all=[...new Set([...specialties,...profileSelection])];return all.map(s=>`<button type="button" class="chip ${profileSelection.includes(s)?'selected':''}" data-specialty="${esc(s)}" aria-pressed="${profileSelection.includes(s)}">${icon(profileSelection.includes(s)?'check':'plus')}${esc(s)}</button>`).join('');}
function profile(){const p=state.profile;profileSelection=[...p.specialties];return heading('Seu trabalho tem valor.','Conte o que você faz. Esse será o ponto de partida para as sugestões do NEXO.')+`<div class="section-tabs"><span>Perfil profissional</span></div><div class="content-grid"><form class="panel" id="profileForm"><section class="form-section"><div class="section-title"><i>${icon('user')}</i><div><h2>Vamos começar por você</h2><p>Como você quer se apresentar para seus próximos clientes?</p></div></div><div class="form-grid"><label>Seu nome<input name="name" value="${esc(p.name)}" required maxlength="100" autocomplete="name"></label><label>Título profissional<input name="title" value="${esc(p.title)}" maxlength="150" placeholder="Ex.: Gestor de tráfego e web designer"></label></div><label class="full-label">Cidade e estado<input name="city" value="${esc(p.city)}" maxlength="150" placeholder="Ex.: Brasília / DF"></label></section><section class="form-section"><div class="section-title"><i>${icon('briefcase')}</i><div><h2>Suas especialidades</h2><p>Selecione suas áreas ou adicione outra.</p></div></div><div class="specialty-options" id="specialtyOptions">${specialtyChips()}</div><div class="add-specialty"><label class="sr-only" for="newSpecialty">Outra especialidade</label><input id="newSpecialty" maxlength="100" placeholder="Outra especialidade"><button type="button" class="btn btn-secondary" data-action="add-specialty">${icon('plus')}Adicionar</button></div><label class="full-label">O que você faz, nas suas palavras<textarea name="description" rows="4" maxlength="5000" placeholder="Ex.: Ajudo pequenos negócios a captar clientes com campanhas Meta Ads e crio sites para apresentar seus serviços.">${esc(p.description)}</textarea></label><p class="hint">Descreva apenas as atividades que você realmente oferece.</p></section><section class="form-section"><div class="section-title"><i>${icon('shield')}</i><div><h2>Seus limites e suas provas</h2><p>Abordagens honestas, baseadas no seu trabalho real.</p></div></div><label>O que você não oferece<textarea name="restrictions" rows="2" maxlength="3000" placeholder="Ex.: Não faço filmagem presencial nem gestão de TikTok.">${esc(p.restrictions)}</textarea></label><label class="full-label">Portfólio e resultados reais <span class="optional">opcional</span><textarea name="portfolio" rows="3" maxlength="5000" placeholder="Cole links dos seus trabalhos e descreva resultados que você pode comprovar.">${esc(p.portfolio)}</textarea></label></section><div class="form-bottom"><p>Você poderá editar estas informações quando quiser.</p><button class="btn btn-primary" type="submit">${icon('save')}Salvar meu perfil</button></div></form><aside><div class="panel profile-card"><div class="profile-avatar">${esc((p.name[0]||'N').toUpperCase())}</div><h2>${esc(p.name||'Seu nome')}</h2><p>${esc(p.title||'Seu próximo capítulo começa aqui')}</p><p>${esc(p.city||'Localização não informada')}</p><div class="specialty-options">${p.specialties.map(x=>`<span class="chip">${esc(x)}</span>`).join('')||'<span class="hint">Suas especialidades aparecerão aqui.</span>'}</div><div class="mini-divider"></div><div class="progress-caption"><span>Perfil configurado</span><span>${[p.description.trim(),p.specialties.length,p.title.trim(),p.portfolio.trim()].filter(Boolean).length}/4</span></div><div class="progress-track"><span style="width:${[p.description.trim(),p.specialties.length,p.title.trim(),p.portfolio.trim()].filter(Boolean).length*25}%"></span></div><p class="mini-note">As informações deste resumo são atualizadas ao salvar o perfil.</p></div><div class="info-box"><h3>${icon('spark')}Você define a direção</h3><p>O catálogo terá apenas os serviços que você revisar e salvar. Uma especialidade não ativa ofertas automaticamente.</p></div></aside></div>`;}
function services(){let list=state.services.filter(s=>(serviceFilter==='all'||(serviceFilter==='active'?s.active:!s.active))&&`${s.name} ${s.specialty}`.toLowerCase().includes(serviceSearch.toLowerCase()));const suggestions=serviceTemplates.filter(t=>state.profile.specialties.includes(t.specialty)&&!state.services.some(s=>s.name===t.name));return heading('O que você quer oferecer?','Seu catálogo define quais soluções poderão entrar em cada abordagem.',`<button class="btn btn-primary" data-action="new-service">${icon('plus')}Novo serviço</button>`)+`<div class="notice">${icon('info')}Cadastre as entregas e os limites de cada serviço. Apenas os serviços ativos poderão ser oferecidos.</div><div class="toolbar"><div class="filters" role="group" aria-label="Filtrar serviços">${[['all','Todos'],['active','Ativos'],['inactive','Inativos']].map(([key,label])=>`<button class="filter ${serviceFilter===key?'active':''}" data-filter="${key}" aria-pressed="${serviceFilter===key}">${label}${key==='all'?` (${state.services.length})`:''}</button>`).join('')}</div><label class="sr-only" for="serviceSearch">Buscar serviço</label><input id="serviceSearch" type="search" placeholder="Buscar no catálogo" value="${esc(serviceSearch)}" style="width:220px;margin:0"></div><div class="service-grid">${list.map(s=>`<article class="service-card"><div class="service-content"><div class="service-top"><div class="stat-icon">${icon('layers')}</div><span class="status-pill ${s.active?'':'off'}">${s.active?'Ativo':'Inativo'}</span></div><span class="eyebrow">${esc(s.specialty)}</span><h3>${esc(s.name)}</h3><p class="service-description">${esc(s.deliverables)}</p><div class="service-meta"><span>${icon('clock')}${esc(s.deadline||'Prazo a definir')}</span><span>${esc(s.price||'Preço a definir')}</span></div>${s.proof?'<p class="hint">Portfólio ou provas registrados</p>':'<p class="hint">Sem provas registradas</p>'}</div><div class="service-actions"><button class="btn btn-ghost" data-action="edit-service" data-id="${esc(s.id)}">${icon('edit')}Editar</button><button class="btn btn-ghost" data-action="toggle-service" data-id="${esc(s.id)}">${s.active?'Desativar':'Ativar'}</button><button class="icon-button" data-action="delete-service" data-id="${esc(s.id)}" aria-label="Excluir ${esc(s.name)}">${icon('trash')}</button></div></article>`).join('')}</div>${!list.length?`<section class="panel empty"><div class="empty-icon">${icon('layers')}</div><h2>${state.services.length?'Nenhum serviço neste filtro':'Seu catálogo começa com o que você sabe fazer'}</h2><p>${state.services.length?'Experimente outro filtro ou termo de busca.':'Cadastre seu primeiro serviço ou revise uma sugestão baseada nas especialidades do seu perfil.'}</p><button class="btn btn-primary" data-action="new-service">${icon('plus')}Cadastrar serviço</button></section>`:''}${suggestions.length?`<div class="suggestion-head"><h2>Ideias para você revisar</h2><p>Sugestões de cadastro por especialidade. Revise o escopo antes de salvar.</p></div><div style="display:grid;gap:12px">${suggestions.map(t=>`<div class="suggestion"><div><h3>${esc(t.name)}</h3><p>${esc(t.specialty)} · Escopo ajustável</p></div><button class="btn btn-secondary" data-action="suggest-service" data-template="${serviceTemplates.indexOf(t)}">Revisar sugestão</button></div>`).join('')}</div>`:''}`;}
const states=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
function search(){const hasActive=state.services.some(s=>s.active);return heading('Onde está sua próxima conexão?','Escolha um segmento e uma região para preparar sua primeira busca.')+`<div class="notice">${icon('info')}Nesta etapa, você salva a configuração da pesquisa. A busca real, os contatos e os diagnósticos serão conectados à IA na próxima etapa.</div>${!hasActive?`<div class="info-box" style="margin:0 0 22px"><h3>${icon('layers')}Seu catálogo ainda está vazio</h3><p><a class="text-link" href="#servicos">Cadastre um serviço ativo</a> para definir o que poderá oferecer às empresas.</p></div>`:''}<div class="content-grid"><form class="panel" id="searchForm"><section class="form-section"><div class="section-title"><i>${icon('search')}</i><div><h2>Prepare sua pesquisa</h2><p>Comece com um nicho e uma região bem definidos.</p></div></div><label>Nicho<select name="niche" required><option value="">Selecione um segmento</option>${['Clínicas odontológicas','Salões de beleza','Barbearias','Restaurantes','Hamburguerias','Oficinas mecânicas','Academias','Pet shops','Imobiliárias','Outro segmento'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="full-label" id="customNicheLabel" hidden>Qual segmento?<input name="customNiche" maxlength="150" placeholder="Digite o nicho"></label><div class="form-grid" style="margin-top:20px"><label>Estado / DF<select name="state" required>${states.map(s=>`<option ${s==='DF'?'selected':''}>${s}</option>`).join('')}</select></label><label>Cidade / região administrativa<input name="city" required maxlength="150" list="cities" placeholder="Ex.: São Sebastião" autocomplete="off"><datalist id="cities"><option value="Brasília"><option value="São Sebastião"><option value="Jardim Botânico"><option value="Ceilândia"><option value="Taguatinga"><option value="Águas Claras"><option value="Guará"><option value="Gama"><option value="Sobradinho"><option value="Samambaia"><option value="Planaltina"></datalist></label></div><div class="form-grid" style="margin-top:20px"><label>Bairro <span class="optional">opcional</span><input name="neighborhood" maxlength="150" placeholder="Ex.: Centro"></label><label>Quantidade pretendida<select name="quantity"><option value="5">Até 5 empresas</option><option value="10">Até 10 empresas</option></select></label></div><p class="hint" style="margin-top:18px">A quantidade é uma meta para a futura busca e não garante empresas encontradas.</p></section><div class="form-bottom"><p>A pesquisa ficará salva como rascunho.</p><button class="btn btn-primary" type="submit">${icon('save')}Salvar pesquisa</button></div></form><aside><div class="tip-card"><div class="stat-icon">${icon('target')}</div><p class="tip-label">COMECE COM FOCO</p><h3>Pequenos lotes.<br>Boas oportunidades.</h3><p>Um nicho e uma região por vez ajudam a revisar as fontes e preparar uma abordagem personalizada.</p></div></aside></div><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Pesquisas preparadas</h2><p>Configurações salvas. Nenhuma busca foi executada.</p></div><span class="status-pill off">${state.drafts.length} rascunhos</span></div>${state.drafts.length?state.drafts.map(d=>`<div class="draft-item"><div class="stat-icon">${icon('search')}</div><div><h3>${esc(d.niche)}</h3><p>${esc(d.city)} / ${esc(d.state)}${d.neighborhood?` · ${esc(d.neighborhood)}`:''} · Até ${d.quantity} empresas</p><p>Rascunho · ${esc(new Date(d.createdAt).toLocaleDateString('pt-BR'))}</p></div><button class="icon-button" data-action="delete-draft" data-id="${esc(d.id)}" aria-label="Excluir pesquisa de ${esc(d.niche)}">${icon('trash')}</button></div>`).join(''):'<div class="empty" style="padding-top:15px"><p>Nenhuma pesquisa preparada. Use o formulário acima para começar.</p></div>'}</section>`;}
function emptyPage(kind){return kind==='empresas'?heading('Cada empresa, uma oportunidade.','Aqui ficarão as empresas pesquisadas e os diagnósticos com suas fontes.')+`<section class="panel empty"><div class="empty-icon">${icon('building')}</div><h2>Sua primeira conexão ainda está por vir</h2><p>A pesquisa com IA será integrada na próxima etapa. Por enquanto, configure seu perfil, seus serviços e prepare uma pesquisa.</p><a class="btn btn-primary" href="#pesquisa">${icon('search')}Preparar pesquisa</a></section>`:heading('O próximo passo, no tempo certo.','Aqui você acompanhará conversas e retornos após registrar seus contatos.')+`<section class="panel empty"><div class="empty-icon">${icon('calendar')}</div><h2>Nenhum retorno por enquanto</h2><p>Após a integração de pesquisa e abordagem, você poderá registrar contatos e organizar os próximos passos. Os retornos serão tarefas para sua revisão.</p><a class="btn btn-secondary" href="#inicio">Voltar à visão geral</a></section>`;}
function settings(){return heading('Seu espaço, suas escolhas.','Controle seus dados e acompanhe as próximas integrações.')+`<div class="settings-grid"><section class="panel"><div class="setting-row"><div><h3>Seus dados neste navegador</h3><p>Perfil, serviços e pesquisas são salvos apenas neste dispositivo e navegador. Exporte uma cópia para guardar ou transferir para outro dispositivo.</p></div><span class="status-pill">Salvamento local</span></div><div class="setting-row" style="border-top:1px solid var(--line)"><div><h3>Cópia dos seus cadastros</h3><p>O arquivo inclui seu perfil, os serviços e os rascunhos. Importar substitui os cadastros atuais após sua confirmação.</p></div><div class="setting-actions"><button class="btn btn-secondary" data-action="export">${icon('download')}Exportar</button><button class="btn btn-ghost" data-action="import">${icon('upload')}Importar</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></div></section><section class="panel"><div class="setting-row"><div><h3>Pesquisa e inteligência artificial</h3><p>Integração planejada com Gemini para pesquisa, diagnóstico e preparação das abordagens. Nenhuma chave é solicitada ou usada nesta versão.</p></div><span class="connection-status">Próxima etapa</span></div><div class="setting-row" style="border-top:1px solid var(--line)"><div><h3>Login e sincronização entre dispositivos</h3><p>Use Minha conta no topo para entrar, salvar os cadastros na conta e carregá-los em outro dispositivo. A sincronização é manual.</p></div><span class="connection-status">Próxima etapa</span></div></section><section class="panel"><div class="setting-row"><div><h3>Sobre o NEXO</h3><p>Prospecção inteligente · v0.1<br>Encontre empresas. Entenda oportunidades. Prepare sua abordagem.</p></div><span class="status-pill off">Uso pessoal</span></div></section></div>`;}
function render(){const next=location.hash.slice(1)||'inicio';route=Object.hasOwn(names,next)?next:'inicio';document.title=`${names[route]} | NEXO`;$('#crumb').textContent=names[route];document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});main.innerHTML=route==='inicio'?home():route==='perfil'?profile():route==='servicos'?services():route==='pesquisa'?search():route==='configuracoes'?settings():emptyPage(route);hydrate();updateChrome();menu(false);window.scrollTo(0,0);}
function menu(open){$('#sidebar').classList.toggle('open',open);$('#scrim').classList.toggle('visible',open);$('#menuToggle').setAttribute('aria-expanded',String(open));}
function openService(s=null){const f=$('#serviceForm');f.reset();$('#dialogTitle').textContent=s?.id?'Editar serviço':s?'Revisar sugestão':'Novo serviço';const options=[...new Set([...state.profile.specialties,...(s?.specialty?[s.specialty]:[])])];f.elements.specialty.innerHTML=`<option value="">Selecione a especialidade</option>${options.map(x=>`<option>${esc(x)}</option>`).join('')}`;if(!options.length){toast('Adicione suas especialidades no perfil primeiro.');location.hash='perfil';return;}for(const k of ['id','name','specialty','deliverables','deadline','price','exclusions','proof'])f.elements[k].value=s?.[k]||'';f.elements.active.checked=s?.active??true;$('#serviceDialog').showModal();}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`NEXO_Backup_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Cópia preparada para download.');}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-specialty],[data-filter]');if(!btn)return;if(btn.dataset.specialty){const value=btn.dataset.specialty;profileSelection=profileSelection.includes(value)?profileSelection.filter(x=>x!==value):[...profileSelection,value];$('#specialtyOptions').innerHTML=specialtyChips();return;}if(btn.dataset.filter){serviceFilter=btn.dataset.filter;main.innerHTML=services();return;}const action=btn.dataset.action;const s=state.services.find(x=>x.id===btn.dataset.id);
if(action==='add-specialty'){const input=$('#newSpecialty'),value=input.value.trim();if(!value)return;if(profileSelection.length>=50)return toast('Limite de 50 especialidades atingido.');if(!profileSelection.some(x=>x.toLowerCase()===value.toLowerCase()))profileSelection.push(value);input.value='';$('#specialtyOptions').innerHTML=specialtyChips();}
if(action==='new-service')openService();
if(action==='edit-service'&&s)openService(s);
if(action==='suggest-service')openService(serviceTemplates[Number(btn.dataset.template)]);
if(action==='toggle-service'&&s){if(save({...state,services:state.services.map(x=>x.id===s.id?{...x,active:!x.active}:x)})){render();toast(s.active?'Serviço desativado.':'Serviço ativado.');}}
if(action==='delete-service'&&s&&confirm(`Excluir o serviço “${s.name}”?`)){if(save({...state,services:state.services.filter(x=>x.id!==s.id)})){render();toast('Serviço excluído.');}}
if(action==='delete-draft'&&confirm('Excluir este rascunho de pesquisa?')){if(save({...state,drafts:state.drafts.filter(x=>x.id!==btn.dataset.id)})){render();toast('Rascunho excluído.');}}
if(action==='export')exportData();if(action==='import')$('#importFile').click();
});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='profileForm'){e.preventDefault();const f=new FormData(e.target);const p=Object.fromEntries(['name','title','city','description','restrictions','portfolio'].map(k=>[k,String(f.get(k)||'').trim()]));if(!p.name)return toast('Informe seu nome.');p.specialties=[...profileSelection];if(save({...state,profile:p})){render();toast('Perfil salvo. Seu catálogo já pode ser configurado.');}}
if(e.target.getAttribute('id')==='serviceForm'){e.preventDefault();const f=new FormData(e.target),id=String(f.get('id'))||crypto.randomUUID();const s=Object.fromEntries(['name','specialty','deliverables','deadline','price','exclusions','proof'].map(k=>[k,String(f.get(k)||'').trim()]));if(!s.name||!s.specialty||!s.deliverables)return toast('Preencha o nome, a especialidade e as entregas.');s.id=id;s.active=f.has('active');const exists=state.services.some(x=>x.id===id);if(!exists&&state.services.length>=500)return toast('Limite de 500 serviços atingido.');if(save({...state,services:exists?state.services.map(x=>x.id===id?s:x):[...state.services,s]})){$('#serviceDialog').close();render();toast('Serviço salvo no seu catálogo.');}}
if(e.target.getAttribute('id')==='searchForm'){e.preventDefault();if(state.drafts.length>=500)return toast('Limite de 500 rascunhos atingido.');const f=new FormData(e.target);const niche=f.get('niche')==='Outro segmento'?String(f.get('customNiche')||'').trim():String(f.get('niche'));if(!niche)return toast('Informe o segmento da pesquisa.');const city=String(f.get('city')||'').trim();if(!city)return toast('Informe a cidade ou região administrativa.');const d={id:crypto.randomUUID(),niche,state:String(f.get('state')),city,neighborhood:String(f.get('neighborhood')||'').trim(),quantity:Number(f.get('quantity')),createdAt:new Date().toISOString()};if(save({...state,drafts:[d,...state.drafts]})){render();toast('Pesquisa salva como rascunho. A busca ainda não foi executada.');}}
});
document.addEventListener('change',async e=>{if(e.target.name==='niche'&&route==='pesquisa'){const custom=e.target.value==='Outro segmento';$('#customNicheLabel').hidden=!custom;$('#customNicheLabel input').required=custom;}if(e.target.name==='state'&&route==='pesquisa'){const input=$('#searchForm [name=city]');input.value='';if(e.target.value==='DF')input.setAttribute('list','cities');else input.removeAttribute('list');}if(e.target.id==='importFile'){const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const next=JSON.parse(await file.text());if(!validState(next))throw Error();if(confirm('Importar esta cópia e substituir o perfil, os serviços e os rascunhos atuais?')){if(save(next)){render();toast('Cadastros restaurados com sucesso.');}}}catch{toast('Arquivo inválido. Selecione uma cópia JSON exportada pelo NEXO.');}e.target.value='';}});
document.addEventListener('input',e=>{if(e.target.id==='serviceSearch'){serviceSearch=e.target.value;const pos=e.target.selectionStart;main.innerHTML=services();const field=$('#serviceSearch');field.focus();field.setSelectionRange(pos,pos);}});
$('#menuToggle').addEventListener('click',()=>menu(!$('#sidebar').classList.contains('open')));$('#scrim').addEventListener('click',()=>menu(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false);if(e.key==='Enter'&&e.target.id==='newSpecialty'){e.preventDefault();$('[data-action="add-specialty"]').click();}});
$('#closeDialog').addEventListener('click',()=>$('#serviceDialog').close());$('#cancelDialog').addEventListener('click',()=>$('#serviceDialog').close());
window.addEventListener('hashchange',render);
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(validState(next)){state=next;render();toast('Cadastros atualizados em outra aba.');}}catch{}}});
render();
if(storageProblem){const alert=document.createElement('div');alert.id='storageWarning';alert.setAttribute('role','alert');alert.textContent='Não foi possível ler seus cadastros salvos. Para evitar sobrescrevê-los, exporte ou restaure uma cópia antes de salvar alterações.';document.body.append(alert);}
